ALTER POLICY "photos read" ON storage.objects USING(bucket_id='body-photos' AND ((public.is_own_student(public.safe_uuid((storage.foldername(name))[1])) AND public.restricted_student_access(public.safe_uuid((storage.foldername(name))[1]))) OR (public.is_trainer_of(public.safe_uuid((storage.foldername(name))[1])) AND public.has_photo_consent(public.safe_uuid((storage.foldername(name))[1])))));
ALTER POLICY "photos upload" ON storage.objects WITH CHECK(bucket_id='body-photos' AND public.is_own_student(public.safe_uuid((storage.foldername(name))[1])) AND public.has_photo_consent(public.safe_uuid((storage.foldername(name))[1])) AND public.restricted_student_access(public.safe_uuid((storage.foldername(name))[1])));
ALTER POLICY "student uploads photos" ON public.body_photos WITH CHECK(public.is_own_student(student_id) AND public.has_photo_consent(student_id) AND public.restricted_student_access(student_id) AND uploaded_by=auth.uid() AND storage_path LIKE student_id::text||'/%');